async def _partner_remote_license(key, device, claim=False):
    key=(key or "").strip().upper()
    if not key:
        return {"valid":False,"reason":"Digite a chave liberada pelo Mega Professor."}
    cache_key=key+":"+device
    cached=_partner_license_cache.get(cache_key)
    if not claim and cached and time.time()-float(cached.get("_ts",0)) < PARTNER_LICENSE_CACHE_SECONDS:
        return {k:v for k,v in cached.items() if k!="_ts"}
    try:
        async with httpx.AsyncClient(timeout=8.0) as client:
            if claim:
                response=await client.post(MASTER_SERVER_URL+"/license/claim",json={"key":key,"device":device})
            else:
                response=await client.get(MASTER_SERVER_URL+"/license/validate",params={"key":key,"device":device})
        data=response.json() if response.status_code==200 else {"valid":False,"reason":f"O Mega Professor recusou a chave (HTTP {response.status_code})."}
    except Exception as exc:
        LOG.warning("Falha ao validar licença no Mega Professor: %s",type(exc).__name__)
        data={"valid":False,"reason":"Não foi possível conectar ao Mega Professor para validar a chave."}
    data["_ts"]=time.time()
    _partner_license_cache[cache_key]=data
    return {k:v for k,v in data.items() if k!="_ts"}

@app.post("/license/activate")
async def partner_license_activate(request: Request):
    raw=await request.body()
    if len(raw)>8192:
        raise HTTPException(status_code=413,detail="Formulário muito grande.")
    fields=urllib.parse.parse_qs(raw.decode("utf-8",errors="replace"),keep_blank_values=True)
    key=str((fields.get("key") or [""])[0]).strip().upper()
    device=request.cookies.get(PARTNER_DEVICE_COOKIE,"")
    if not re.fullmatch(r"[0-9a-f]{64}",device):
        device=secrets.token_hex(32)
    status=await _partner_remote_license(key,device,claim=True)
    if not status.get("valid"):
        message=html.escape(str(status.get("reason") or "Chave inválida."))
        return HTMLResponse(PARTNER_LICENSE_PAGE.replace("__ERROR__",f'<div class="err">{message}</div>'),status_code=403)
    response=RedirectResponse("/",status_code=303)
    response.set_cookie(PARTNER_LICENSE_COOKIE,key,max_age=60*60*24*370,httponly=True,samesite="lax",secure=request.url.scheme=="https")
    response.set_cookie(PARTNER_DEVICE_COOKIE,device,max_age=60*60*24*370,httponly=True,samesite="lax",secure=request.url.scheme=="https")
    return response

